package com.dronefleet.service;
import com.dronefleet.config.AppConfig;import com.dronefleet.domain.*;import com.dronefleet.event.*;import com.dronefleet.repository.*;import com.dronefleet.strategy.*;import java.util.*;import java.util.concurrent.*;import java.time.*;import java.util.logging.*;
public final class DeliveryService{private static final Logger LOG=Logger.getLogger(DeliveryService.class.getName());private final DroneRepository drones;private final DeliveryRepository deliveries;private final AuditRepository audit;private final AssignmentStrategy strategy;private final EventBus bus;private final AppConfig cfg;private final ExecutorService executor=Executors.newCachedThreadPool();
 public DeliveryService(DroneRepository d,DeliveryRepository del,AuditRepository a,AssignmentStrategy s,EventBus b,AppConfig c){drones=d;deliveries=del;audit=a;strategy=s;bus=b;cfg=c;}
 public synchronized Delivery createAndAssign(int packageId,double weight,double distance,String type,String user){PackageItem item=new PackageItem(packageId,weight,distance,LocalDateTime.now());if(deliveries.packageExists(packageId)) throw new IllegalArgumentException("Package ID already exists. Use a new package ID.");Delivery d=new Delivery(deliveries.nextId(),item,LocalDateTime.now());deliveries.savePackage(item);Optional<Drone> chosen=strategy.select(drones.findAll(),new AssignmentContext(item,type));if(chosen.isEmpty()){d.fail("No suitable drone available");deliveries.save(d);bus.publish(new DeliveryEvent(d.id(),d.status(),LocalDateTime.now(),d.failureReason()));return d;}Drone drone=chosen.get();double use=DroneCalculator.battery(drone,item);if(!drone.hasBatteryFor(use))throw new IllegalStateException("Battery became insufficient before assignment");drone.markBusy();drone.consumeBattery(use);d.assign(drone.id(),DroneCalculator.minutes(drone,item),use,DroneCalculator.charge(drone,item));deliveries.save(d);d.start();deliveries.save(d);drones.save(drone);audit.log(user,"DELIVERY_ASSIGNED","DELIVERY",String.valueOf(d.id()),"drone="+drone.id()+" strategy="+strategy.name());bus.publish(new DeliveryEvent(d.id(),d.status(),LocalDateTime.now(),"Delivery started"));LOG.info("Delivery #"+d.id()+" assigned to D-"+drone.id());startSimulation(d,drone,user);return d;}
 private void startSimulation(Delivery d,Drone drone,String user){executor.submit(()->{try{long ms=Math.max(1L,(long)d.estimatedMinutes()*cfg.simulationMillisPerMinute());Thread.sleep(ms);synchronized(this){Delivery current=deliveries.findAll().stream().filter(x->x.id()==d.id()).findFirst().orElse(d);if(current.status()==DeliveryStatus.IN_TRANSIT){current.complete();deliveries.save(current);drone.recordDelivery(current.item().distance(),current.charge());drone.release();drones.save(drone);audit.log(user,"DELIVERY_COMPLETED","DELIVERY",String.valueOf(current.id()),"revenue="+current.charge());bus.publish(new DeliveryEvent(current.id(),current.status(),LocalDateTime.now(),"Delivery completed"));}}}catch(InterruptedException e){Thread.currentThread().interrupt();LOG.warning("Delivery simulation interrupted #"+d.id());}catch(Exception e){LOG.log(Level.SEVERE,"Delivery simulation failed",e);}});}
 public List<Delivery> all(){return deliveries.findAll();}public void shutdown(){executor.shutdownNow();}
}
